34	constexpr const char OPTION_LISTEN_IP_INFO[] = "llm.ListenIpInfo";
35	constexpr const char OPTION_DEVICE_ID[] = "llm.DeviceId";
36	constexpr const char OPTION_SYNC_CACHE_WAIT_TIME[] = "llm.SyncKvCacheWaitTime";
37	constexpr const char OPTION_BUF_POOL_CFG[] = "llm.BufPoolCfg";
38	constexpr const char OPTION_ENABLE_SET_ROLE[] = "llm.EnableSwitchRole";
39	constexpr const char OPTION_LOCAL_COMM_RES[] = "llm.LocalCommRes";
