43	// status codes
44	constexpr Status LLM_SUCCESS = 0x0U;
45	constexpr Status LLM_FAILED = 0xFFFFFFFFU;
46	constexpr Status LLM_WAIT_PROC_TIMEOUT = 0x5010B001U;
47	constexpr Status LLM_KV_CACHE_NOT_EXIST = 0x5010B002U;
48	constexpr Status LLM_PARAM_INVALID = 0x5010B005U;
49	constexpr Status LLM_NOT_YET_LINK = 0x5010B007U;
50	constexpr Status LLM_ALREADY_LINK = 0x5010B008U;
51	constexpr Status LLM_LINK_FAILED = 0x5010B009U;
52	constexpr Status LLM_UNLINK_FAILED = 0x5010B00AU;
53	constexpr Status LLM_NOTIFY_PROMPT_UNLINK_FAILED = 0x5010B00BU;
54	constexpr Status LLM_CLUSTER_NUM_EXCEED_LIMIT = 0x5010B00CU;
55	constexpr Status LLM_PROCESSING_LINK = 0x5010B00DU;
56	constexpr Status LLM_DEVICE_OUT_OF_MEMORY = 0x5010B00EU;
57	constexpr Status LLM_EXIST_LINK = 0x5010B018U;
58	constexpr Status LLM_FEATURE_NOT_ENABLED = 0x5010B019U;
59	constexpr Status LLM_TIMEOUT = 0x5010B01AU;
60	constexpr Status LLM_LINK_BUSY = 0x5010B01BU;
61	constexpr Status LLM_OUT_OF_MEMORY = 0x5010B01CU;
62	
63	// data types
64	using ge::DT_BF16;
65	using ge::DT_BOOL;
66	using ge::DT_COMPLEX128;
67	using ge::DT_COMPLEX32;
68	using ge::DT_COMPLEX64;
69	using ge::DT_DOUBLE;
70	using ge::DT_DUAL;
71	using ge::DT_DUAL_SUB_INT8;
72	using ge::DT_DUAL_SUB_UINT8;
73	using ge::DT_FLOAT;
74	using ge::DT_FLOAT16;
75	using ge::DT_FLOAT4_E1M2;
76	using ge::DT_FLOAT4_E2M1;
77	using ge::DT_FLOAT6_E2M3;
78	using ge::DT_FLOAT6_E3M2;
79	using ge::DT_FLOAT8_E4M3FN;
80	using ge::DT_FLOAT8_E5M2;
81	using ge::DT_FLOAT8_E8M0;
82	using ge::DT_HIFLOAT8;
83	using ge::DT_INT16;
84	using ge::DT_INT2;
85	using ge::DT_INT32;
86	using ge::DT_INT4;
87	using ge::DT_INT64;
88	using ge::DT_INT8;
89	using ge::DT_QINT16;
90	using ge::DT_QINT32;
91	using ge::DT_QINT8;
92	using ge::DT_QUINT16;
93	using ge::DT_QUINT8;
94	using ge::DT_RESOURCE;
95	using ge::DT_STRING;
96	using ge::DT_STRING_REF;
