159	class ASCEND_FUNC_VISIBILITY LlmDataDist {
160	 public:
161	  /**
162	   * @brief 构造函数
163	   * @param cluster_id 集群ID
164	   * @param role 当前LlmDataDist的角色
165	   */
166	  LlmDataDist(uint64_t cluster_id, LlmRole role);
167	
168	  /**
169	   * @brief 析构函数
170	   */
171	  ~LlmDataDist();
172	
173	  /**
174	   * @brief 初始化LlmDataDist, 在调用其他接口前需要先调用该接口
175	   * @param options 初始化所需的选项
176	   * @return 成功:LLM_SUCCESS, 失败:其它.
177	   */
178	  Status Initialize(const std::map<AscendString, AscendString> &options);
179	
180	  /**
181	   * @brief 终结LlmDataDist
182	   */
183	  void Finalize();
184	
185	  /**
186	   * @brief 设置角色
187	   * @param role 目标角色
188	   * @param options 设置角色时传入的选项，设置成Prompt时需要包含OPTION_LISTEN_IP_INFO
189	   * @return 成功:LLM_SUCCESS, 失败:其它
190	   */
191	  Status SetRole(LlmRole role, const std::map<AscendString, AscendString> &options = {});
192	
193	  /**
194	   *  @brief 进行llm datadist间建链
195	   *  @param [in] clusters 需要建链的cluster信息
196	   *  @param [in] timeout_in_millis 超时时间，单位ms
197	   *  @param [out] rets 每个cluster建链结果
198	   *  @return 成功:LLM_SUCCESS, 失败:其它
199	   */
200	  Status LinkLlmClusters(const std::vector<ClusterInfo> &clusters, std::vector<Status> &rets,
201	                         int32_t timeout_in_millis = 1000);
202	
203	  /**
204	   *  @brief 进行llm datadist间断链
205	   *  @param [in] clusters 需要断链的cluster信息
206	   *  @param [in] timeout_in_millis 超时时间，单位ms
207	   *  @param [in] force_flag 是否强制断链
208	   *  @param [out] rets 每个cluster断链结果
209	   *  @return 成功:LLM_SUCCESS, 失败:其它
210	   */
211	  Status UnlinkLlmClusters(const std::vector<ClusterInfo> &clusters, std::vector<Status> &rets,
212	                           int32_t timeout_in_millis = 1000, bool force_flag = false);
213	
214	  /**
215	   *  @brief 分配Cache
216	   *  @param [in] cache_desc cache描述
217	   *  @param [out] cache 分配出的cache
218	   *  @return 成功:LLM_SUCCESS, 失败:其它
219	   */
220	  Status AllocateCache(const CacheDesc &cache_desc, Cache &cache);
221	
222	  /**
223	   *  @brief 释放Cache
224	   *  @param [in] cache_id cache的id
225	   *  @return 成功:LLM_SUCCESS, 失败:其它. Cache不存在或已释放也会返回LLM_SUCCESS
226	   */
227	  Status DeallocateCache(int64_t cache_id);
228	
229	  /**
230	   * @brief 从远端拉取连续KV Cache
231	   * @param [in] src_cache_index 远端cache索引
232	   * @param [in] dst_cache 拉取到的本地目标cache
233	   * @param [in] batch_index 拉取到的本地目标cache的batch index
234	   * @param [in] size 拉取的大小, -1表示拉取源cache的完整数据
235	   * @param [in] ext_param 扩展参数
236	   * @return 成功:LLM_SUCCESS, 失败:其它
237	   */
238	  Status PullKvCache(const CacheIndex &src_cache_index, const Cache &dst_cache, uint32_t batch_index = 0U,
239	                     int64_t size = -1, const KvCacheExtParam &ext_param = {});
240	
241	  /**
242	   * @brief 从远端拉取KV blocks
243	   * @param [in] src_cache_index 远端cache索引
244	   * @param [in] dst_cache 拉取到的本地目标cache
245	   * @param [in] src_blocks 源block列表
246	   * @param [in] dst_blocks 目标block列表
247	   * @param [in] ext_param 扩展参数
248	   * @return 成功:LLM_SUCCESS, 失败:其它
249	   */
250	  Status PullKvBlocks(const CacheIndex &src_cache_index, const Cache &dst_cache,
251	                      const std::vector<uint64_t> &src_blocks, const std::vector<uint64_t> &dst_blocks,
252	                      const KvCacheExtParam &ext_param = {});
253	
254	  /**
255	   * @brief 拷贝连续Cache
256	   * @param src_cache 源Cache
257	   * @param dst_cache 目标Cache
258	   * @param src_batch_index 源batch index
259	   * @param dst_batch_index 目标batch index
260	   * @param offset 偏移
261	   * @param size 大小, -1表示拷贝源cache的完整数据
262	   * @return 成功:LLM_SUCCESS, 失败:其它
263	   */
264	  Status CopyKvCache(const Cache &src_cache, const Cache &dst_cache, uint32_t src_batch_index = 0U,
265	                     uint32_t dst_batch_index = 0U, uint64_t offset = 0U, int64_t size = -1);
266	
267	  /**
268	   * @brief 拷贝KV block
269	   * @param src_cache 源Cache
270	   * @param dst_cache 目标Cache
271	   * @param src_blocks 源block列表
272	   * @param dst_blocks_list 目标block列表，可以为多组，即可以同时拷贝到多个目标
273	   * @return 成功:LLM_SUCCESS, 失败:其它
274	   */
275	  Status CopyKvBlocks(const Cache &src_cache, const Cache &dst_cache, const std::vector<uint64_t> &src_blocks,
276	                      const std::vector<std::vector<uint64_t>> &dst_blocks_list);
277	
278	  /**
279	   * @brief 向远端push连续KV Cache
280	   * @param [in] src_cache 本地cache
281	   * @param [in] dst_cache_index 远端cache索引
282	   * @param [in] src_batch_index 本地cache的batch index
283	   * @param [in] size 推送的大小, -1表示推送源cache的完整数据
284	   * @param [in] ext_param 扩展参数
285	   * @return 成功:LLM_SUCCESS, 失败:其它
286	   */
287	  Status PushKvCache(const Cache &src_cache, const CacheIndex &dst_cache_index, uint32_t src_batch_index = 0U,
288	                     int64_t size = -1, const KvCacheExtParam &ext_param = {});
289	
290	  /**
291	   * @brief 向远端push KV blocks
292	   * @param [in] src_cache 本地cache
293	   * @param [in] dst_cache_index 远端cache索引
294	   * @param [in] src_blocks 源block列表
295	   * @param [in] dst_blocks 目标block列表
296	   * @param [in] ext_param 扩展参数
297	   * @return 成功:LLM_SUCCESS, 失败:其它
298	   */
299	  Status PushKvBlocks(const Cache &src_cache, const CacheIndex &dst_cache_index,
300	                      const std::vector<uint64_t> &src_blocks, const std::vector<uint64_t> &dst_blocks,
301	                      const KvCacheExtParam &ext_param = {});
302	
303	  /**
304	   * @brief 注册KV内存
305	   * @param [in] cache_desc 内存描述信息
306	   * @param [in] addrs 内存地址列表
307	   * @param [in] cfg 注册配置信息
308	   * @param [out] cache_id 内存cache
309	   * @return 成功:LLM_SUCCESS, 失败:其它
310	   */
311	  Status RegisterKvCache(const CacheDesc &cache_desc, const std::vector<uint64_t> &addrs, const RegisterCfg &cfg,
312	                         int64_t &cache_id);
313	
314	  /**
315	   * @brief 解注册KV内存
316	   * @param [in] cache_id 内存cache
317	   * @return 成功:LLM_SUCCESS, 失败:其它
318	   */
319	  Status UnregisterKvCache(int64_t cache_id);
320	
321	 private:
322	  class LlmDataDistImpl;
323	  std::unique_ptr<LlmDataDistImpl> impl_;
324	};
325	}  // namespace llm_datadist
326	
327	#endif  // CANN_GRAPH_ENGINE_INC_EXTERNAL_LLM_DATADIST_LLM_DATA_DIST_H_
