133	int32_t NotifyUnlinkDone(const char *remote_ip, uint16_t port) {
134	  sockaddr_in addr{};
135	  addr.sin_family = AF_INET;
136	  addr.sin_port = htons(port);
137	  if (inet_pton(AF_INET, remote_ip, &addr.sin_addr) != 1) {
138	    printf("[ERROR] Parse control ip failed, ip = %s\n", remote_ip);
139	    return -1;
140	  }
141	  for (int32_t retry = 0; retry < kNotifyRetryTimes; ++retry) {
142	    int32_t fd = socket(AF_INET, SOCK_STREAM, 0);
143	    if (fd < 0) {
144	      printf("[ERROR] Create control socket failed\n");
145	      return -1;
146	    }
147	    if (connect(fd, reinterpret_cast<sockaddr *>(&addr), sizeof(addr)) == 0) {
148	      auto nsent = send(fd, &kUnlinkDoneMessage, sizeof(kUnlinkDoneMessage), 0);
149	      CloseSocket(fd);
150	      if (nsent == static_cast<ssize_t>(sizeof(kUnlinkDoneMessage))) {
151	        printf("[INFO] Notify decoder unlink done success\n");
152	        return 0;
153	      }
154	      printf("[ERROR] Send decoder unlink done failed\n");
155	      return -1;
156	    }
157	    CloseSocket(fd);
158	    usleep(kNotifyRetryIntervalUs);
159	  }
160	  printf("[ERROR] Notify decoder unlink done timeout, ip = %s, port = %u\n", remote_ip,
161	         static_cast<unsigned int>(port));
162	  return -1;
163	}
