165	int32_t PushCache(LlmDataDist &llm_datadist, int64_t cache_id) {
166	  std::vector<uint64_t> prompt_blocks{5, 6, 7};
167	  std::vector<uint64_t> decoder_blocks{5, 6, 7};
168	  // 可以使用PushKvBlock推送多块block的数据
169	  Cache cache{};
170	  cache.cache_id = cache_id;
171	  auto ret = LLM_SUCCESS;
172	  CacheIndex cache_index = {};
173	  cache_index.cluster_id = 1;
174	  cache_index.cache_id = 1;
175	  for (uint32_t i = 0U; i < kNumTensors; ++i) {
176	    KvCacheExtParam param{};
177	    param.src_layer_range = std::pair<int32_t, int32_t>(i, i);
178	    param.dst_layer_range = std::pair<int32_t, int32_t>(i, i);
179	    param.tensor_num_per_layer = 1;
180	    ret = llm_datadist.PushKvBlocks(cache, cache_index, prompt_blocks, decoder_blocks, param);
181	    if (ret != LLM_SUCCESS) {
182	      printf("[ERROR] PushKvBlocks failed, ret = %u, errmsg: %s\n", ret, GetRecentErrMsg());
183	      return -1;
184	    }
185	  }
186	  printf("[INFO] PushKvBlocks success\n");
187	
188	  // 也可以使用PushKvCache推送一个batch中的连续数据
189	  CacheIndex cache_index2 = {};
190	  cache_index2.cluster_id = 1;
191	  cache_index2.cache_id = 1;
192	  cache_index2.batch_index = kPushBatchIndex;
193	  KvCacheExtParam param2{};
194	  param2.src_layer_range = std::pair<int32_t, int32_t>(0, 0);
195	  param2.dst_layer_range = std::pair<int32_t, int32_t>(0, 0);
196	  param2.tensor_num_per_layer = kPushTensorNumPerLayer;
197	  ret = llm_datadist.PushKvCache(cache, cache_index2, kPushBatchIndex, -1, param2);
198	  if (ret != LLM_SUCCESS) {
199	    printf("[ERROR] PushKvCache failed, ret = %u, errmsg: %s\n", ret, GetRecentErrMsg());
200	    return -1;
201	  }
202	  printf("[INFO] PushKvCache success\n");
203	  return 0;
204	}
