206	void Finalize(LlmDataDist &llm_datadist, int64_t cache_id, bool linked, const char *remote_ip,
207	              const std::vector<void *> buffers) {
208	  if (linked) {
209	    auto ret = Unlink(llm_datadist, remote_ip);
210	    if (ret != 0) {
211	      printf("[ERROR] Unlink failed, ret = %d\n", ret);
212	    } else {
213	      printf("[INFO] Unlink success\n");
214	    }
215	  }
216	  if (cache_id > 0) {
217	    auto ret = llm_datadist.UnregisterKvCache(cache_id);
218	    if (ret != 0) {
219	      printf("[ERROR] UnregisterKvCache failed, ret = %u, errmsg: %s\n", ret, GetRecentErrMsg());
220	    } else {
221	      printf("[INFO] UnregisterKvCache success\n");
222	    }
223	  }
224	  for (auto buffer : buffers) {
225	    aclrtFree(buffer);
226	  }
227	  llm_datadist.Finalize();
228	}
229	
230	int32_t RunPromptSample(const char *device_id, const char *local_ip, const char *remote_ip,
231	                        const std::string &transfer_backend, const std::string local_comm_res) {
232	  printf("[INFO] Prompt Sample start\n");
233	  // 1. 初始化
234	  LlmDataDist llm_datadist(kPromptClusterId, LlmRole::kPrompt);
235	  if (Initialize(llm_datadist, device_id, local_ip, transfer_backend, local_comm_res) != 0) {
236	    printf("[ERROR] Initialize LlmDataDist failed\n");
237	    return -1;
238	  }
239	  // 2. 注册内存地址
240	  CacheDesc cache_desc{};
241	  cache_desc.num_tensors = kNumTensors;
242	  cache_desc.data_type = DT_INT32;
243	  cache_desc.shape = kTensorShape;
244	  std::vector<uint64_t> tensor_addrs;
245	  std::vector<void *> buffers;
246	  for (uint32_t i = 0U; i < kNumTensors; ++i) {
247	    int32_t *buffer = nullptr;
248	    CHECK_ACL(aclrtMalloc((void **)&buffer, kTensorSize, ACL_MEM_MALLOC_HUGE_ONLY));
249	
250	    // init device buffer
251	    std::vector<int32_t> host_buffer(kTensorSize / sizeof(int32_t));
252	    std::iota(host_buffer.begin(), host_buffer.end(), 0);
253	    CHECK_ACL(aclrtMemcpy(buffer, kTensorSize, &host_buffer[0], kTensorSize, ACL_MEMCPY_HOST_TO_DEVICE));
254	
255	    tensor_addrs.emplace_back(reinterpret_cast<uint64_t>(buffer));
256	    buffers.emplace_back(reinterpret_cast<void *>(buffer));
257	  }
258	  int64_t cache_id = -1;
259	  bool linked = false;
260	  auto ret = llm_datadist.RegisterKvCache(cache_desc, tensor_addrs, {}, cache_id);
261	  if (ret != LLM_SUCCESS) {
262	    printf("[ERROR] RegisterKvCache failed, ret = %u, errmsg: %s\n", ret, GetRecentErrMsg());
263	    Finalize(llm_datadist, cache_id, linked, remote_ip, buffers);
264	    return -1;
265	  }
266	  // 3. RegisterKvCache成功后，可以获取cache中各tensor的地址用于后续操作
267	  printf("[INFO] RegisterKvCache success\n");
268	  for (size_t i = 0U; i < tensor_addrs.size(); ++i) {
269	    printf("[INFO] Tensor[%zu] addr = %p\n", i, reinterpret_cast<void *>(tensor_addrs[i]));
270	  }
271	
272	  // 等待decoder注册完成
273	  std::this_thread::sleep_for(std::chrono::seconds(kWaitTime));
274	
275	  // 4. 与decoder建链
276	  if (Link(llm_datadist, local_ip, remote_ip) != 0) {
277	    Finalize(llm_datadist, cache_id, linked, remote_ip, buffers);
278	    return -1;
279	  }
280	  linked = true;
281	
282	  // 5. 向decoder push cache
283	  if (PushCache(llm_datadist, cache_id) != 0) {
284	    Finalize(llm_datadist, cache_id, linked, remote_ip, buffers);
285	    return -1;
286	  }
287	
288	  // 6. 解除链路并通知decoder后释放Cache与llmDataDist
289	  if (Unlink(llm_datadist, remote_ip) != 0) {
290	    Finalize(llm_datadist, cache_id, linked, remote_ip, buffers);
291	    return -1;
292	  }
293	  linked = false;
294	  if (NotifyUnlinkDone(remote_ip, kDecoderControlPort) != 0) {
295	    Finalize(llm_datadist, cache_id, linked, remote_ip, buffers);
296	    return -1;
297	  }
298	
299	  Finalize(llm_datadist, cache_id, linked, remote_ip, buffers);
300	  printf("[INFO] Prompt Sample end\n");
301	  return 0;
302	}
303	
304	int main(int32_t argc, char **argv) {
305	  if (argc < kExpectedArgCnt - 2 || argc > kExpectedArgCnt) {
306	    printf(
307	        "[ERROR] expect args(device_id, localHostIp, remoteHostIp, [transfer_backend], [local_comm_res]), "
308	        "but got %d\n",
309	        argc - 1);
310	    return -1;
311	  }
312	  const auto device_id = argv[kArgIndexDeviceId];
313	  const auto local_ip = argv[kArgIndexLocalIp];
314	  const auto remote_ip = argv[kArgIndexRemoteIp];
315	  printf("[INFO] device_id = %s, local_ip = %s, remote_ip = %s\n", device_id, local_ip, remote_ip);
316	  std::string transfer_backend;
317	  std::string local_comm_res;
318	  if (argc > kArgIndexTransferBackend) {
319	    transfer_backend = argv[kArgIndexTransferBackend];
320	    printf("[INFO] transfer_backend = %s\n", transfer_backend.c_str());
321	  }
322	  if (argc > kArgIndexLocalCommRes) {
323	    local_comm_res = argv[kArgIndexLocalCommRes];
324	    printf("[INFO] local_comm_res = %s\n", local_comm_res.c_str());
325	  }
326	  auto ret = RunPromptSample(device_id, local_ip, remote_ip, transfer_backend, local_comm_res);
327	  return ret;
328	}
