30	std::string RoleToString(LlmRole role) {
31	  static const std::map<LlmRole, std::string> kRoleToStr{
32	      {LlmRole::kPrompt, llm::kPrompt},
33	      {LlmRole::kDecoder, llm::kDecoder},
