59	    LLM_CHK_STATUS_RET(ConvertIpInfos(cluster_info.remote_ip_infos, llm_cluster_info.remote_ip_infos),
60	                       "Failed to parse remote ip info, index = %zu", i);
61	    LLM_CHK_STATUS_RET(ConvertIpInfos(cluster_info.local_ip_infos, llm_cluster_info.local_ip_infos),
62	                       "Failed to parse local ip info, index = %zu", i);
63	    ret.emplace_back(std::move(llm_cluster_info));
64	  }
65	  return LLM_SUCCESS;
