78	Status CheckKvCacheExtParam(const KvCacheExtParam &ext_param, bool check_range_same = false) {
79	  LLM_CHK_BOOL_RET_STATUS((ext_param.src_layer_range.first >= -1 && ext_param.src_layer_range.second >= -1 &&
80	                           ext_param.src_layer_range.first <= ext_param.src_layer_range.second),
81	                          ge::LLM_PARAM_INVALID, "Invalid src layer:[%d,%d], layer need >= -1, and first <= second.",
82	                          ext_param.src_layer_range.first, ext_param.src_layer_range.second);
83	  LLM_CHK_BOOL_RET_STATUS((ext_param.dst_layer_range.first >= -1 && ext_param.dst_layer_range.second >= -1 &&
84	                           ext_param.dst_layer_range.first <= ext_param.dst_layer_range.second),
85	                          ge::LLM_PARAM_INVALID, "Invalid dst layer:[%d,%d], layer need >= -1, and first <= second.",
86	                          ext_param.dst_layer_range.first, ext_param.dst_layer_range.second);
87	  LLM_CHK_BOOL_RET_STATUS((ext_param.tensor_num_per_layer > 0), ge::LLM_PARAM_INVALID,
88	                          "Invalid tensor_num_per_layer:[%u], tensor_num_per_layer need > 0.",
89	                          static_cast<uint32_t>(ext_param.tensor_num_per_layer));
90	  if (check_range_same) {
91	    LLM_CHK_BOOL_RET_STATUS((ext_param.src_layer_range.second - ext_param.src_layer_range.first) ==
92	                                (ext_param.dst_layer_range.second - ext_param.dst_layer_range.first),
93	                            ge::LLM_PARAM_INVALID, "src_layer_range should keep the same size as dst_layer_range.");
94	  }
95	  return LLM_SUCCESS;
