181	Status LlmDataDist::LlmDataDistImpl::Initialize(const std::map<AscendString, AscendString> &options) {
182	  std::lock_guard<std::mutex> lk(mutex_);
183	  LLM_CHK_BOOL_RET_SPECIAL_STATUS((llm_data_dist_.IsInitialized()), LLM_SUCCESS, "Already initialized");
184	  const auto &role_str = RoleToString(role_);
185	  LLM_CHK_BOOL_RET_STATUS((!role_str.empty()), LLM_PARAM_INVALID, "Invalid role: %d", static_cast<int32_t>(role_));
186	  LLM_DISMISSABLE_GUARD(clear_guard, [this]() { device_ids_.clear(); });
187	  LLM_CHK_STATUS_RET(llm::LLMUtils::ParseDeviceId(options, device_ids_, llm_datadist::OPTION_DEVICE_ID),
188	                     "Failed to get device_id from options");
189	  LLM_CHK_BOOL_RET_STATUS(!device_ids_.empty(), ge::LLM_PARAM_INVALID, "option %s can not be empty.",
190	                          llm_datadist::OPTION_DEVICE_ID);
191	  auto init_options = options;
192	  // set ge.exec.deviceId
193	  init_options[ge::OPTION_EXEC_DEVICE_ID] = init_options[llm_datadist::OPTION_DEVICE_ID];
194	  if (init_options.find(ge::OPTION_SESSION_DEVICE_ID) == init_options.end()) {
195	    // ensure array index before.
196	    init_options[ge::OPTION_SESSION_DEVICE_ID] = std::to_string(device_ids_[0U]).c_str();
197	  }
198	  init_options[llm::LLM_OPTION_ROLE] = role_str.c_str();
199	  ge::AscendString local_comm_res;
200	  const auto &rank_it = init_options.find(llm_datadist::OPTION_LOCAL_COMM_RES);
201	  if (rank_it != init_options.cend()) {
202	    local_comm_res = rank_it->second;
203	  }
204	
205	  std::string ip;
206	  uint32_t port = 0U;
207	  const auto &iter = options.find(llm_datadist::OPTION_LISTEN_IP_INFO);
208	  if (iter != options.cend()) {
209	    LLMLOGI("role:%s listen option %s=%s", role_str.c_str(), llm_datadist::OPTION_LISTEN_IP_INFO,
210	            iter->second.GetString());
211	    LLM_CHK_STATUS_RET(llm::LLMUtils::ParseListenIpInfo(options, ip, port), "Failed to parse listen ip info");
212	    init_options[llm::kLlmOptionListenIp] = ip.c_str();
213	    init_options[llm::kLlmOptionListenPort] = std::to_string(port).c_str();
214	  }
215	  init_options[llm::kLlmOptionEnableRemoteCacheAccessible] = "1";
216	  LLM_CHK_STATUS_RET(llm_data_dist_.LLMDataDistInitialize(init_options), "Failed to initialize LLMDataDist.");
217	  LLM_DISMISS_GUARD(clear_guard);
218	  return ge::SUCCESS;
219	}
