284	  std::map<std::string, std::string> switch_options;
285	  for (const auto &key_and_value : options) {
286	    (void)switch_options.emplace(key_and_value.first.GetString(), key_and_value.second.GetString());
287	  }
288	  std::string ip;
289	  uint32_t port = 0U;
290	  const auto &iter = options.find(llm_datadist::OPTION_LISTEN_IP_INFO);
291	  if (iter != options.cend()) {
292	    LLMLOGI("Target role:%s listen option %s=%s", role_str.c_str(), llm_datadist::OPTION_LISTEN_IP_INFO,
293	            iter->second.GetString());
294	    LLM_CHK_STATUS_RET(llm::LLMUtils::ParseListenIpInfo(options, ip, port), "Failed to parse listen ip info");
295	    switch_options[llm::kLlmOptionListenIp] = ip;
296	    switch_options[llm::kLlmOptionListenPort] = std::to_string(port);
