306	Status LlmDataDist::LlmDataDistImpl::PushData(const Cache &src_cache, const KvCacheExtParam &ext_param,
307	                                              llm::TransferCacheConfig &transfer_cache_config,
308	                                              llm::TransferBlockConfig &transfer_block_config) {
309	  auto src_layer_index = ext_param.src_layer_range.first;
310	  auto dst_layer_index = ext_param.dst_layer_range.first;
311	  // push one appointed layer
312	  if (src_layer_index >= 0 && (ext_param.src_layer_range.first == ext_param.src_layer_range.second)) {
313	    transfer_cache_config.layer_index = static_cast<uint64_t>(src_layer_index);
314	    transfer_cache_config.dst_layer_index = static_cast<uint64_t>(dst_layer_index);
315	    return llm_data_dist_.TransferCache(0U, transfer_cache_config, transfer_block_config);
316	  } else {
317	    int32_t cache_max_layer;
318	    // push all ranges without appointed layer
319	    if (src_layer_index < 0) {
320	      src_layer_index = 0;
321	      dst_layer_index = 0;
322	      cache_max_layer = GetCacheMaxLayer(src_cache, ext_param);
323	      // push the appointed mult-layers
324	    } else {
325	      cache_max_layer = ext_param.src_layer_range.second;
326	    }
327	
328	    for (; src_layer_index <= cache_max_layer; src_layer_index++, dst_layer_index++) {
329	      transfer_cache_config.layer_index = static_cast<uint64_t>(src_layer_index);
330	      transfer_cache_config.dst_layer_index = static_cast<uint64_t>(dst_layer_index);
331	      const auto ret = llm_data_dist_.TransferCache(0U, transfer_cache_config, transfer_block_config);
332	      LLM_CHK_STATUS_RET(ret, "[PushKvCache] failed, src_layer_index = %d.", src_layer_index);
333	    }
334	  }
335	  return LLM_SUCCESS;
336	}
