338	Status LlmDataDist::LlmDataDistImpl::PushKvCache(const Cache &src_cache, const CacheIndex &dst_cache_index,
339	                                                 uint32_t src_batch_index, int64_t size,
340	                                                 const KvCacheExtParam &ext_param) {
341	  LLM_CHK_BOOL_RET_STATUS((llm_data_dist_.IsInitialized()), ge::FAILED, "LlmDataDist is not initialized");
342	  LLM_CHK_BOOL_RET_STATUS(src_cache.cache_desc.placement == CachePlacement::kDevice, LLM_PARAM_INVALID,
343	                          "Only support push to device cache");
344	  LLM_CHK_BOOL_RET_STATUS((size == -1), LLM_PARAM_INVALID, "Invalid size (%ld), size only support -1 currently.", size);
345	
346	  LLM_CHK_STATUS_RET(CheckKvCacheExtParam(ext_param, true));
347	  LLM_CHK_BOOL_RET_STATUS(((ext_param.src_layer_range.first >= 0) ||
348	                           (ext_param.src_layer_range.first == -1 && src_cache.cache_desc.num_tensors > 0)),
349	                          LLM_PARAM_INVALID, "Invalid src layer:%d, layer need >= 0 or -1 with valid num_tensors.",
350	                          ext_param.src_layer_range.first);
351	
352	  constexpr uint64_t kCacheKeyByIdType = 2UL;
353	  llm::TransferCacheConfig transfer_cache_config{};
354	  transfer_cache_config.src_cache_id = src_cache.cache_id;
355	  transfer_cache_config.batch_index = src_batch_index;
356	  transfer_cache_config.cluster_id = dst_cache_index.cluster_id;
357	  transfer_cache_config.dst_cache_id = dst_cache_index.cache_id;
358	  transfer_cache_config.model_id_or_cache_id = dst_cache_index.cache_id;
359	  transfer_cache_config.dst_batch_index = static_cast<uint64_t>(dst_cache_index.batch_index);
360	  transfer_cache_config.type = kCacheKeyByIdType;
361	  transfer_cache_config.tensor_num_per_layer = ext_param.tensor_num_per_layer;
362	  llm::TransferBlockConfig transfer_block_config{};
363	  return PushData(src_cache, ext_param, transfer_cache_config, transfer_block_config);
364	}
