404	Status LlmDataDist::LlmDataDistImpl::RegisterKvCache(const CacheDesc &cache_desc, const std::vector<uint64_t> &addrs,
405	                                                     const RegisterCfg &cfg, int64_t &cache_id) {
406	  (void)cfg;
407	  LLM_CHK_BOOL_RET_STATUS((llm_data_dist_.IsInitialized()), ge::FAILED, "LlmDataDist is not initialized");
408	  LLM_CHK_BOOL_RET_STATUS(!addrs.empty(), LLM_PARAM_INVALID, "addrs cannot be empty");
409	  LLM_CHK_BOOL_RET_STATUS(addrs.size() == static_cast<size_t>(cache_desc.num_tensors), LLM_PARAM_INVALID,
410	                          "addrs length:%zu should be equal to num_tensors:%u", addrs.size(), cache_desc.num_tensors);
411	  for (auto addr : addrs) {
412	    LLM_CHK_BOOL_RET_STATUS(addr != 0UL, LLM_PARAM_INVALID, "addr cannot be nullptr");
413	  }
414	
415	  llm::CacheDesc internal_cache_desc{};
416	  internal_cache_desc.num_tensors = cache_desc.num_tensors;
417	  internal_cache_desc.data_type = static_cast<ge::DataType>(cache_desc.data_type);
418	  internal_cache_desc.shape = cache_desc.shape;
419	  internal_cache_desc.placement = static_cast<uint32_t>(cache_desc.placement);
420	  internal_cache_desc.seq_len_dim_index = 0;
421	  internal_cache_desc.remote_accessible = true;
422	  internal_cache_desc.cache_mem_type = llm::CacheMemType::MIX;
423	
424	  llm::Cache internal_cache{};
425	  std::vector<uintptr_t> per_device_tensor_addrs;
426	  for (auto addr : addrs) {
427	    per_device_tensor_addrs.emplace_back(static_cast<uintptr_t>(addr));
428	  }
429	  internal_cache.per_device_tensor_addrs = {per_device_tensor_addrs};
430	  LLM_CHK_STATUS_RET(llm_data_dist_.RegisterCache(internal_cache_desc, internal_cache), "Failed to register cache");

